mapper.select:
SELECT primary_key as enquiryCode,type, enquiry_number, enquiry_name,buyer,
seller, customer_data_code, enterprise_code as ownedEnterpriseCode,
sell_enquiry_belong as userCode, user_name, language, payment_strategy, column_titles,
amount_title,product_detail,remark,state,enquiry_time,data_version,purchase_enquiry,son_enterprise_code,business_belong,sign_areas
FROM ${tableName}
WHERE
enterprise_code= #{currentEnterpriseCode}
AND delete_flag= 'f'

    AND customer_data_code = #{customerDataCode}


    AND sell_enquiry_belong IN

        #{userCode}



    AND enquiry_number LIKE '%'|| #{enquiryNumber} ||'%'


    AND state = #{state}


    AND enquiry_time >= #{enquiryTimePreDate}


    AND enquiry_time <= #{enquiryTimePostDate}


    ${dataScopeParams.dataScope}


    AND business_belong = #{businessBelong}

ORDER BY create_time DESC

mapper.update:
UPDATE ${tableName}
SET seller              = #{model.seller},
    buyer              = #{model.buyer},
    customer_data_code = #{model.customerDataCode},
    sell_enquiry_belong = #{model.userCode},
    user_name           = #{model.userName},
    data_version        = #{model.dataVersion},
    son_enterprise_code = #{model.sonEnterpriseCode}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.enquiryCode}
  AND data_version = #{clientDataVersion}

UPDATE ${tableName}
SET buyer        = #{model.buyer},
    customer_data_code = #{model.customerDataCode},
    data_version = #{model.dataVersion},
    son_enterprise_code = #{model.sonEnterpriseCode}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.enquiryCode}
  AND data_version = #{clientDataVersion}

UPDATE ${tableName}
SET state        = #{model.state},
    data_version = #{model.dataVersion},
    son_enterprise_code = #{model.sonEnterpriseCode}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.enquiryCode}
  AND data_version = #{clientDataVersion}

